package dev.raven.profileformat;
import org.json.*;import java.util.*;import java.math.BigDecimal;
/** Versioned data only. No executable requests, hardware paths or runtime ownership in portable profiles. */
public final class PortableProfiles {
 public static final String[] KINDS={"led","fan","cpu"};
 public static JSONObject empty()throws JSONException{JSONObject o=new JSONObject().put("schema",1);for(String k:KINDS)o.put(k,new JSONObject());return o;}
 static void require(boolean b,String s)throws Exception{if(!b)throw new Exception(s);}
 static void keys(JSONObject o,String... allowed)throws Exception{Set<String> set=new HashSet<>(Arrays.asList(allowed));for(Iterator<String> i=o.keys();i.hasNext();)require(set.contains(i.next()),"Unsupported profile field");}
 public static String name(Object value,boolean global)throws Exception{require(value instanceof String,"Invalid profile name");String s=(String)value;require(s.length()<=160&&(global||!s.trim().isEmpty())&&!s.matches("(?s).*[\\x00-\\x1f\\x7f].*"),"Invalid profile name");return s;}
 public static long number(Object value,long min,long max)throws Exception{require(value instanceof Number,"Invalid profile number");long n=new BigDecimal(value.toString()).longValueExact();require(n>=min&&n<=max,"Profile number outside supported bounds");return n;}
 static void color(JSONObject p,String k,boolean required)throws Exception{if(!p.has(k)&&!required)return;require(p.get(k) instanceof String&&p.getString(k).matches("[0-9a-fA-F]{6}"),"Invalid LED color");}
 public static void validate(JSONObject o)throws Exception{keys(o,"schema","led","fan","cpu");number(o.get("schema"),1,1);require(o.toString().length()<=8*1024*1024,"Raven profiles exceed backup limit");for(String kind:KINDS){JSONObject all=o.getJSONObject(kind);require(all.length()<=2000,"Too many Raven profiles");for(Iterator<String> i=all.keys();i.hasNext();){String n=i.next();name(n,false);JSONObject p=all.getJSONObject(n);
  if(kind.equals("led")){keys(p,"left","right","sideLeft","sideRight","sideLights","lightingZones","lightBrightness","lightMask");color(p,"left",true);color(p,"right",true);color(p,"sideLeft",false);color(p,"sideRight",false);if(p.has("sideLights"))require(Arrays.asList("keep","on","off").contains(p.getString("sideLights")),"Invalid side light setting");if(p.has("lightingZones"))number(p.get("lightingZones"),1,4);if(p.has("lightMask"))require(p.getString("lightMask").matches("[01]{4}"),"Invalid light mask");if(p.has("lightBrightness")){JSONArray a=p.getJSONArray("lightBrightness");require(a.length()==4,"Invalid LED brightness count");for(int j=0;j<4;j++)number(a.get(j),0,100);}}
  else if(kind.equals("fan")){keys(p,"points","kind","manual","zone","stockMode");require(!n.endsWith(" · stock"),"Reserved stock fan name");long stock=p.has("stockMode")?number(p.get("stockMode"),-1,5):-1;if(stock>=0){require(stock==0||stock==1||stock==4||stock==5,"Invalid stock fan mode");continue;}require(Arrays.asList("manual","curve").contains(p.getString("kind")),"Invalid fan profile type");number(p.get("manual"),10,100);require(p.get("zone") instanceof String&&(p.getString("zone").matches("[0-9]{1,3}")||p.getString("zone").equals("cpu-average")),"Invalid fan sensor");String points=p.getString("points");String[] pairs=points.split(",",-1);require(pairs.length>=3&&pairs.length<=8,"Invalid fan curve");long lastT=34,lastS=0;for(String pair:pairs){require(pair.matches("[0-9]+:[0-9]+"),"Invalid curve point");String[] v=pair.split(":");long t=Long.parseLong(v[0]),speed=Long.parseLong(v[1]);require(t>lastT&&t<=78&&speed>=lastS&&speed<=100&&(speed==0||speed>=10),"Invalid fan curve ordering");lastT=t;lastS=speed;}require(lastS>=10,"Curve needs active cooling");}
  else{keys(p,"mode","minimum","maximum");require(!Arrays.asList("Normal","Performance","High Performance").contains(n),"Reserved stock CPU name");number(p.get("mode"),0,2);JSONArray a=p.getJSONArray("minimum"),b=p.getJSONArray("maximum");require(a.length()==3&&b.length()==3,"Invalid CPU profile limits");for(int j=0;j<3;j++){long low=number(a.get(j),1,j==2?3000000000L:10000000),high=number(b.get(j),1,j==2?3000000000L:10000000);require(low<=high,"Reversed CPU limits");}}
 }}}
 public static JSONObject merge(JSONObject before,JSONObject incoming,boolean replace)throws Exception{validate(incoming);JSONObject result=replace?empty():new JSONObject(before.toString());validate(result);for(String kind:KINDS){JSONObject src=incoming.getJSONObject(kind),dst=result.getJSONObject(kind);for(Iterator<String> i=src.keys();i.hasNext();){String n=i.next();dst.put(n,new JSONObject(src.getJSONObject(n).toString()));}}validate(result);return result;}
 public static int count(JSONObject o)throws Exception{int n=0;for(String k:KINDS)n+=o.getJSONObject(k).length();return n;}
}
